                if (rc) briefHtml += ' <span class="ecom-sim-recap">' + this._fill('brief_recap', { m: rc.period, n: rc.newCustomers || 0, r: rc.repeatCustomers || 0, c: this._money(rc.cac), p: this._money(rc.profit) }) + '</span>';
                briefEl.innerHTML = briefHtml;
            }

            // the validator refuses a budget above the cash in the bank, so the input says the same
            var budgetMaxEl = document.getElementById('budgetInput');
            var liveDs = (state && state.domainState) || (window.mySimulation && window.mySimulation.state ? window.mySimulation.state.domainState : null);
            if (budgetMaxEl && liveDs && typeof liveDs.cash === 'number') budgetMaxEl.setAttribute('max', String(Math.max(0, Math.floor(liveDs.cash))));

            if (window.mySimulation) {
                var cashCv = document.getElementById('cashChart');
                if (cashCv) { cashCv.setAttribute('role', 'img'); cashCv.setAttribute('aria-label', window.mySimulation.t('chart_cash_alt')); }
                var ltvCv = document.getElementById('ltvCacChart');
                if (ltvCv) { ltvCv.setAttribute('role', 'img'); ltvCv.setAttribute('aria-label', window.mySimulation.t('chart_ltv_alt')); }
            }

            var eventBanner = document.getElementById('eventBanner');
            if (eventBanner) {
                var evtMsg = this._getEventPreview(month);
                if (evtMsg) {
                    eventBanner.style.display = 'block';
                    var iconEl = document.getElementById('eventIcon');
                    var textEl = document.getElementById('eventText');
                    if (iconEl) iconEl.textContent = evtMsg.icon;
                    if (textEl) textEl.innerHTML = evtMsg.text;
                } else {
                    eventBanner.style.display = 'none';
                }
            }
        }

        // month 1 is April 2026, the launch month in the case; named in the language of the page
        _calendarMonth(month) {
            if (!(month >= 1 && month <= 12)) return '';
            try {
                var d = new Date(Date.UTC(2026, 3 + (month - 1), 15));
                var name = d.toLocaleDateString(this._lang() === 'es' ? 'es-ES' : 'en-US', { month: 'long', year: 'numeric', timeZone: 'UTC' });
                return name.charAt(0).toUpperCase() + name.slice(1);
            } catch (e) { return ''; }
        }

        _dec(v, n) {
            var out = (v || 0).toFixed(n);
            return this._lang() === 'es' ? out.replace('.', ',') : out;
        }

        // results of last month for the briefing recap: the round just computed, else the saved history
        _recapFor(m) {
            if (m < 1) return null;
            if (this._lastRecap && this._lastRecap.period === m) return this._lastRecap;
            var hist = window.mySimulation && window.mySimulation.state ? window.mySimulation.state.history : null;
            if (Array.isArray(hist)) {
                for (var i = hist.length - 1; i >= 0; i--) {
                    var r = hist[i] && hist[i].results;
                    if (r && r.period === m) return r;
                }
            }
            return null;
        }

        _lang() {
            var l = (window.vcI18n && window.vcI18n._lang) || document.documentElement.lang || 'en';
            return String(l).slice(0, 2) === 'es' ? 'es' : 'en';
        }

        _t(key) {
            return window.mySimulation ? window.mySimulation.t(key) : key;
        }

        _getEventPreview(month) {
            if (!window.mySimulation) return null;
            var key = { 3: 'event_viral', 6: 'event_supplier', 7: 'event_fraud', 8: 'event_badreviews', 10: 'event_competitor', 11: 'event_ios' }[month];
            return key ? { icon: '', text: window.mySimulation.t(key) } : null;
        }

        _applyEvents(ds, month) {
            ds.cpmMultiplier = 1;
            ds.cogsMultiplier = 1;
            ds.convMultiplier = 1;
            ds.chargebackRate = 0;

            if (month === 3) {
                ds.convMultiplier = 2.5;
            } else if (month === 6) {
                ds.cogsMultiplier = 1.35;
            } else if (month === 7) {
                ds.chargebackRate = 0.03;
            } else if (month === 8) {
                ds.convMultiplier = 0.7;
                ds.nps = Math.max(20, ds.nps - 15);
            } else if (month === 10) {
                ds.cpmMultiplier = 1.6;
            } else if (month === 11) {
                ds.cpmMultiplier = 1.3;
            }
        }

        validateDecisions(decisions) {
            var budgetEl = document.getElementById('budgetInput');
            if (budgetEl) decisions.marketingBudget = parseFloat(budgetEl.value);

            var tofuEl = document.getElementById('tofuInput');
            if (tofuEl) decisions.tofuPct = parseInt(tofuEl.value);

            var bofuEl = document.getElementById('bofuInput');
            if (bofuEl) decisions.bofuPct = parseInt(bofuEl.value);

            var priceEl = document.getElementById('priceInput');
            if (priceEl) decisions.price = parseFloat(priceEl.value);

            var fulfillEl = document.getElementById('fulfillmentSelect');
            if (fulfillEl) decisions.fulfillment = fulfillEl.value;

            if (isNaN(decisions.marketingBudget) || decisions.marketingBudget < 0) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_warning'), 'warning');
                return false;
            }

            var cash = window.mySimulation.state.domainState.cash;
            if (decisions.marketingBudget > Math.max(0, cash)) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_exceed'), 'warning');
                return false;
            }

            var tofu = decisions.tofuPct || 0;
            var bofu = decisions.bofuPct || 0;
            if (tofu + bofu > 100 || tofu < 0 || bofu < 0) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('alloc_warning'), 'warning');
                return false;
            }

            if (!decisions.price || decisions.price < 10 || decisions.price > 200) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('price_warning'), 'warning');
                return false;
            }

            if (!this.FULFILLMENT_MODELS[decisions.fulfillment]) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('fulfill_warning'), 'warning');
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var month = state.currentPeriod;

            this._applyEvents(ds, month);
            if (!Array.isArray(ds.decisionLog)) ds.decisionLog = [];
            ds.decisionLog.push({ m: month, budget: d.marketingBudget, price: d.price, ful: d.fulfillment, tofu: d.tofuPct || 0, bofu: d.bofuPct || 0, cashBefore: Math.round(ds.cash) });

            // demand responds to price: the USD 59 band converts best, conversion falls away above it
            var priceFactor = Math.exp(-this.PRICE_SENS * ((d.price || this.REF_PRICE) - this.REF_PRICE));

            var tofuPct = (d.tofuPct || 0) / 100;
            var bofuPct = (d.bofuPct || 0) / 100;
            var mofuPct = Math.max(0, 1 - tofuPct - bofuPct);

            var tofuBudget = d.marketingBudget * tofuPct;
            var bofuBudget = d.marketingBudget * bofuPct;
            var mofuBudget = d.marketingBudget * mofuPct;

            // frequency saturation: on a young brand audience the CPM rises about 10% per USD 1,000 of monthly spend
            var cpm = 8 * ds.cpmMultiplier * (1 + (d.marketingBudget || 0) / 10000);
            var tofuImpressions = (tofuBudget / Math.max(cpm, 0.01)) * 1000;
            var tofuClicks = tofuImpressions * 0.012;
            var tofuConversions = Math.round(tofuClicks * 0.008 * ds.convMultiplier * priceFactor);
            // the warmed audience is a stock that decays: a fifth of it leaves the retargeting window each month
            ds.audiencePool = Math.round(ds.audiencePool * 0.8) + Math.round(tofuClicks * 0.3);

            // retargeting reaches the warmed audience that awareness spend has built
            var mofuReach = Math.min(mofuBudget / 1.5, ds.audiencePool * 0.6);
            var mofuConversions = Math.round(mofuReach * 0.05 * ds.convMultiplier * priceFactor);

            // conversion ads can only reach shoppers already in market for the brand: a base of
            // category intent plus the audience built by awareness; spend above that buys nothing
            var inMarket = 100 + ds.audiencePool * 0.6;
            var bofuReach = Math.min(bofuBudget / 3, inMarket);
            ds.bofuWaste = (ds.bofuWaste || 0) + Math.max(0, bofuBudget - inMarket * 3);
            var brandQualityBonus = ds.brandEquity / 500;
            var bofuConversions = Math.round(bofuReach * (0.04 + brandQualityBonus) * ds.convMultiplier * priceFactor);

            var emailConversions = Math.round(ds.emailList * 0.003 * priceFactor);
            var organicConversions = Math.round(ds.brandEquity * 0.15 * priceFactor);

            var newCustomers = Math.max(0, tofuConversions + mofuConversions + bofuConversions + emailConversions + organicConversions);

            var fm = this.FULFILLMENT_MODELS[d.fulfillment] || this.FULFILLMENT_MODELS.threePL;

            var repeatCustomers = 0;
            for (var i = 0; i < ds.cohorts.length; i++) {
                var c = ds.cohorts[i];
                var age = month - c.month;
                if (age > 0) {
                    repeatCustomers += Math.round(c.size * ds.repeatRate * Math.pow(0.7, age) * fm.repeatFactor);
                }
            }

            var totalOrders = newCustomers + repeatCustomers;
            var revenue = totalOrders * d.price;

            var unitCost = this.UNIT_COST * ds.cogsMultiplier;
            var cogs = totalOrders * unitCost;

            var fulfillCost = totalOrders * fm.costPerOrder;
            var chargebacks = revenue * ds.chargebackRate;
            var platformFees = revenue * 0.035;
            var totalCosts = cogs + fulfillCost + d.marketingBudget + chargebacks + platformFees;
            var profit = revenue - totalCosts;

            var cac = newCustomers > 0 ? d.marketingBudget / newCustomers : 0;
            var grossMargin = Math.max(0, 1 - (unitCost / Math.max(d.price, 1)) - (fm.costPerOrder / Math.max(d.price, 1)) - 0.035);
            var ltv = d.price * grossMargin * (1 + ds.repeatRate * 3);
            var ltvCac = cac > 0 ? Math.round((ltv / cac) * 100) / 100 : 0;

            ds.cash += profit;

            if (ds.cash < 0) {
                var loanPenalty = Math.abs(ds.cash) * 0.2;
                ds.cash -= loanPenalty;
            }

            ds.totalRevenue += revenue;
            ds.totalProfit += profit;
            ds.totalCustomers += newCustomers;
            ds.totalMarketing = (ds.totalMarketing || 0) + d.marketingBudget;
            ds.lastLtv = ltv;

            ds.brandEquity += fm.brandBonus;
            if (profit > 0) ds.brandEquity += 0.5;
            if (ds.nps > 60) ds.brandEquity += 1;
            if (ds.nps < 40) ds.brandEquity -= 0.5;
            ds.brandEquity = Math.max(0, Math.min(100, ds.brandEquity));

            ds.repeatRate = Math.min(0.40, ds.repeatRate + 0.008 * (ds.brandEquity / 50));
            ds.nps = Math.max(0, Math.min(100, ds.nps + (profit > 0 ? 1 : -2) + fm.npsDelta));
            ds.emailList += Math.round(newCustomers * 0.6);

            if (newCustomers > 0) {
                ds.cohorts.push({ month: month, size: newCustomers });
            }

            ds.cashHistory.push(Math.round(ds.cash));
            ds.revenueHistory.push(Math.round(revenue));
            ds.profitHistory.push(Math.round(profit));
            ds.ltvCacHistory.push(ltvCac);
            ds.cacHistory.push(Math.round(cac));

            // one composite for the period score, the band and the debrief (EQIL 14.1)
            var overallScore = this._composite(ds);
            var band = this._band(overallScore);
            ds.performanceTier = band;
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore, tier: band });

            this._lastRecap = { period: month, newCustomers: newCustomers, repeatCustomers: repeatCustomers, cac: Math.round(cac), profit: Math.round(profit) };

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            return {
                period: month,
                newCustomers: newCustomers,
                repeatCustomers: repeatCustomers,
                totalOrders: totalOrders,
                revenue: Math.round(revenue),
                profit: Math.round(profit),
                cac: Math.round(cac),
                ltv: Math.round(ltv),
                ltvCac: ltvCac,
                cash: Math.round(ds.cash),
                brandEquity: Math.round(ds.brandEquity),
                overallScore: overallScore,
                score: overallScore,
                totalScore: overallScore,
                composite: overallScore
            };
        }

        // Score anchored to the case benchmarks: LTV:CAC 2.5x in twelve months, a 15% net margin,
        // USD 8,000 cumulative profit, brand equity 60, ending with the starting cash. The two ratio
        // parts count in proportion to the scale reached (800 customers): a ratio on a handful of
        // customers is not a growth engine. Bands derived from the expert and random-play distributions.
        _composite(ds, wantParts) {
            var cust = ds.totalCustomers || 0;
            var netMarginPct = ds.totalRevenue > 0 ? Math.round((ds.totalProfit / ds.totalRevenue) * 100) : 0;
            var cacCum = cust > 0 ? (ds.totalMarketing || 0) / cust : 0;
            var ltvCacCum = cacCum > 0 ? (ds.lastLtv || 0) / cacCum : 0;
            var scale = Math.min(1, cust / 800);
            var parts = {
                margin: scale * Math.min(30, Math.max(0, netMarginPct) * 2),
                ltvcac: scale * Math.min(25, ltvCacCum * 10),
                profit: Math.min(20, Math.max(0, (ds.totalProfit || 0) / 400)),
                brand: Math.min(15, (ds.brandEquity || 0) * 0.25),
                cash: Math.min(10, Math.max(0, (ds.cash || 0) / 1500))
            };
            if (wantParts) { parts.penalty = ds.cash < 0; return parts; }
            var s = 0;
            s += parts.margin;
            s += parts.ltvcac;
            s += parts.profit;
            s += parts.brand;
            s += parts.cash;
            s = Math.round(s);
            if (ds.cash < 0) s = Math.max(0, s - 20);
            return Math.max(0, Math.min(100, s));
        }

        _band(score) {
            if (score >= 60) return 'excellent';
            if (score >= 45) return 'very_good';
            if (score >= 30) return 'good';
            return 'needs_improvement';
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash',
                function(v) { return '$' + Math.round(v).toLocaleString(); });
            uiManager.bind('revenueDisplay', 'domainState.totalRevenue',
                function(v) { return '$' + Math.round(v).toLocaleString(); });
            uiManager.bind('customersDisplay', 'domainState.totalCustomers',
                function(v) { return v.toLocaleString(); });
            uiManager.bind('cacDisplay', 'results.cac',
                function(v) { return '$' + (v || 0); });
            uiManager.bind('ltvCacDisplay', 'results.ltvCac',
                function(v) { return (v || 0).toFixed(1) + ':1'; });
            uiManager.bind('brandDisplay', 'domainState.brandEquity',
                function(v) { return Math.round(v) + '/100'; });
        }

        getChartConfig() {
            return {
                cashChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: this._t('chart_cash'),
                                data: [],
                                borderColor: '#27ae60',
                                backgroundColor: 'rgba(39,174,96,0.1)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.2
                            },
                            {
                                label: this._t('chart_revenue'),
                                data: [],
                                borderColor: '#2980b9',
                                backgroundColor: 'rgba(41,128,185,0.08)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: this._t('chart_cash_title') } },
                        scales: { y: { beginAtZero: false } }
                    }
                },
                ltvCacChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: this._t('chart_ltv'),
                                data: [],
                                borderColor: '#e74c3c',
                                backgroundColor: 'rgba(231,76,60,0.1)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.2
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: this._t('chart_ltv_title') },
                            annotation: {}
                        },
                        scales: {
                            y: { beginAtZero: true, suggestedMax: 6 }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var labels = (ds.cashHistory || []).map(function(_, i) { return 'M' + (i + 1); });
            return {
                cashChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.cashHistory || [] },
                        { data: ds.revenueHistory || [] }
                    ]
                },
                ltvCacChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.ltvCacHistory || [] }
                    ]
                }
            };
        }

        _finalDomain(history) {
            var ds = null;
            try { ds = window.mySimulation && window.mySimulation.state ? window.mySimulation.state.domainState : null; } catch (e) { ds = null; }
            if ((!ds || !Array.isArray(ds.decisionLog) || !ds.decisionLog.length) && history && history.length) {
                var last = history[history.length - 1];
                if (last && last.domainState) ds = last.domainState;
            }
            return ds || {};
        }

        // Mistakes read from the run itself (decisionLog in domainState), never from what the player did not do
        _detectMistakes(ds) {
            var log = Array.isArray(ds.decisionLog) ? ds.decisionLog : [];
            var out = [];
            if (!log.length) return out;
            var burn = null, priceSum = 0, drop = 0, firstDrop = null;
            for (var i = 0; i < log.length; i++) {
                var e = log[i];
                if (!burn && e.cashBefore > 0 && e.budget > 0.4 * e.cashBefore) burn = e;
                priceSum += e.price || 0;
                if (e.ful === 'dropship') { drop++; if (!firstDrop) firstDrop = e; }
            }
            var avgPrice = priceSum / log.length;
            if (burn) out.push({ id: 'burn', month: burn.m, a: Math.round(burn.budget), b: Math.round(burn.cashBefore) });
            if (avgPrice >= 90) out.push({ id: 'pricedout', month: log[0].m, a: Math.round(avgPrice) });
            else if (avgPrice <= 52) out.push({ id: 'discount', month: log[0].m, a: Math.round(avgPrice) });
            if (drop >= 4) out.push({ id: 'dropship', month: firstDrop.m, a: drop });
            if ((ds.bofuWaste || 0) > 0.15 * Math.max(1, ds.totalMarketing || 0)) out.push({ id: 'bofucap', month: 0, a: Math.round(ds.bofuWaste) });
            return out;
        }

        _fill(key, vals) {
            var s = this._t(key);
            for (var k in vals) { if (Object.prototype.hasOwnProperty.call(vals, k)) s = s.split('{' + k + '}').join(String(vals[k])); }
            return s;
        }

        _money(v) {
            var n = Math.round(v || 0);
            return (n < 0 ? '-$' : '$') + Math.abs(n).toLocaleString(this._lang() === 'es' ? 'es-ES' : 'en-US');
        }

        getPerformanceSummary(history) {
            history = history || [];
            var ds = this._finalDomain(history);
            var score = this._composite(ds);
            var tier = this._band(score);
            var cust = ds.totalCustomers || 0;
            var cacCum = cust > 0 ? (ds.totalMarketing || 0) / cust : 0;
            var ltvCacCum = cacCum > 0 ? (ds.lastLtv || 0) / cacCum : 0;
            var netMarginPct = ds.totalRevenue > 0 ? Math.round((ds.totalProfit / ds.totalRevenue) * 100) : 0;
            var mistakes = this._detectMistakes(ds);
            var self = this;

            var insights = [];
            mistakes.forEach(function(mk) {
                if (mk.id === 'burn') insights.push(self._fill('ins_burn', { m: mk.month, a: self._money(mk.a), b: self._money(mk.b) }));
                if (mk.id === 'discount') insights.push(self._fill('ins_discount', { a: self._money(mk.a) }));
                if (mk.id === 'pricedout') insights.push(self._fill('ins_pricedout', { a: self._money(mk.a) }));
                if (mk.id === 'dropship') insights.push(self._fill('ins_dropship', { n: mk.a, b: Math.round(ds.brandEquity || 0) }));
                if (mk.id === 'bofucap') insights.push(self._fill('ins_bofucap', { a: self._money(mk.a) }));
            });
            if (cacCum > 0) insights.push(this._fill(ltvCacCum >= 2.5 ? 'ins_ltv_good' : (ltvCacCum >= 1 ? 'ins_ltv_low' : 'ins_ltv_neg'), { r: this._dec(ltvCacCum, 2), c: this._money(cacCum) }));
            else insights.push(this._fill('ins_nospend', { n: cust }));
            insights.push(this._fill((ds.totalProfit || 0) > 0 ? 'ins_profit_pos' : 'ins_profit_neg', { p: this._money(ds.totalProfit), m: netMarginPct }));
            if (insights.length < 3) insights.push(this._fill('ins_cash', { c: this._money(ds.cash), n: cust }));
            insights = insights.slice(0, 5);

            var turning;
            var log = Array.isArray(ds.decisionLog) ? ds.decisionLog : [];
            var prof = Array.isArray(ds.profitHistory) ? ds.profitHistory : [];
            if (mistakes.length && mistakes[0].month) {
                turning = this._fill('tp_' + mistakes[0].id, { m: mistakes[0].month });
            } else {
                var cum = 0, be = 0;
                for (var i = 0; i < prof.length; i++) { cum += prof[i]; if (!be && cum > 0) be = i + 1; }
                turning = be ? this._fill('tp_breakeven', { m: be }) : this._fill('tp_never', { m: log.length || prof.length });
            }

            return {
                eurekaScore: score,
                overallScore: score,
                totalScore: score,
                composite: score,
                score: score,
                performance: tier,
                performanceKey: tier,
                performanceLabel: this._t('tier_' + tier),
                totalProfit: Math.round(ds.totalProfit || 0),
                finalCash: Math.round(ds.cash || 0),
                totalCustomers: cust,
                netMarginPct: netMarginPct,
                ltvCacCum: Math.round(ltvCacCum * 100) / 100,
                cacCum: Math.round(cacCum),
                finalBrand: Math.round(ds.brandEquity || 0),
                mistakes: mistakes.map(function(mk) { return mk.id; }),
                scoreParts: this._composite(ds, true),
                turningPoint: turning,
                insights: insights,
                totalPeriods: history.length || log.length
            };
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            var t = this._t.bind(this);
            var self = this;
            var esc = function(v) { return String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
            var kpi = function(label, value) { return '<div class="ecom-cm-kpi"><div class="ecom-cm-kpi-label">' + esc(label) + '</div><div class="ecom-cm-kpi-value">' + esc(value) + '</div></div>'; };
            var html = '<div class="ecom-cm" role="status">';
            html += '<p class="ecom-cm-score">' + esc(summary.overallScore || 0) + '/100 <span class="ecom-cm-tier">' + esc(summary.performanceLabel || '') + '</span></p>';
            html += '<div class="ecom-cm-kpis">' + kpi(t('cm_profit'), this._money(summary.totalProfit)) + kpi(t('cm_cash'), this._money(summary.finalCash)) + kpi(t('cm_customers'), (summary.totalCustomers || 0).toLocaleString()) + kpi(t('cm_ltvcac'), this._dec(summary.ltvCacCum, 2) + ':1') + '</div>';
            html += '<h4 class="ecom-cm-h">' + esc(t('cm_turning')) + '</h4><p>' + esc(summary.turningPoint || '') + '</p>';
            html += '<h4 class="ecom-cm-h">' + esc(t('cm_insights')) + '</h4><ul>';
            (summary.insights || []).forEach(function(s) { html += '<li>' + esc(s) + '</li>'; });
            html += '</ul>';
            var sp = summary.scoreParts;
            if (sp) {
                var one = function(v) { return (Math.round((v || 0) * 10) / 10).toLocaleString(self._lang() === 'es' ? 'es-ES' : 'en-US'); };
                var prow = function(label, v, max) { return '<li>' + esc(label) + ': ' + esc(one(v)) + ' / ' + esc(max) + ' ' + esc(t('part_points')) + '</li>'; };
                html += '<h4 class="ecom-cm-h">' + esc(t('cm_parts')) + '</h4><ul class="ecom-cm-parts">';
                html += prow(t('part_margin'), sp.margin, 30) + prow(t('part_ltvcac'), sp.ltvcac, 25) + prow(t('part_profit'), sp.profit, 20) + prow(t('part_brand'), sp.brand, 15) + prow(t('part_cash'), sp.cash, 10);
                if (sp.penalty) html += '<li>' + esc(t('part_penalty')) + ': -20 ' + esc(t('part_points')) + '</li>';
                html += '</ul><p class="ecom-cm-note">' + esc(t('cm_parts_note')) + '</p>';
            }
            html += '<h4 class="ecom-cm-h">' + esc(t('cm_questions')) + '</h4><ol><li>' + esc(t('q1')) + '</li><li>' + esc(t('q2')) + '</li><li>' + esc(t('q3')) + '</li></ol></div>';
            return html;
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.cash < 0) return window.mySimulation.t('hint_cash_negative');
            if (results.ltvCac > 0 && results.ltvCac < 1) return window.mySimulation.t('hint_ltvcac_bad');
            if (results.ltvCac >= 3) return window.mySimulation.t('hint_ltvcac_great');
            if (results.profit < 0) return window.mySimulation.t('hint_loss');
            if (results.newCustomers < 5) return window.mySimulation.t('hint_low_acq');
            return null;
        }

