            return [
                { key: 'results.revenue',       label: 'Revenue',    i18nKey: 'col_revenue',    formatter: function(v) { return '$' + (v || 0).toLocaleString(); } },
                { key: 'results.newCustomers',   label: 'New Cust.',  i18nKey: 'col_new_cust' },
                { key: 'results.repeatCustomers',label: 'Repeat',     i18nKey: 'col_repeat' },
                { key: 'results.cac',            label: 'CAC',        i18nKey: 'col_cac',        formatter: function(v) { return '$' + (v || 0); } },
                { key: 'results.ltvCac',         label: 'LTV:CAC',    i18nKey: 'col_ltvcac',     formatter: function(v) { return (v || 0).toFixed(1) + ':1'; } },
                { key: 'results.profit',         label: 'Profit',     i18nKey: 'col_profit',     formatter: function(v) { return '$' + (v || 0).toLocaleString(); } },
                { key: 'results.cash',           label: 'Cash',       i18nKey: 'col_cash',       formatter: function(v) { return '$' + (v || 0).toLocaleString(); } }
            ];
        }

